15	func runServer(ctx context.Context, opts Options) (*Dispatch, error) {
16		token, err := lookupCurrentToken()
17		if err != nil {
18			return nil, fmt.Errorf("reading credentials: %w", err)
19		}
20		if token == "" {
21			return nil, errors.New("dispatch requires login — run `entire login`")
22		}
23	
24		now := nowUTC()
25		sinceInput := strings.TrimSpace(opts.Since)
26		if sinceInput == "" {
27			sinceInput = "7d"
28		}
29		since, err := ParseSinceAtNow(sinceInput, now)
30		if err != nil {
31			return nil, err
32		}
33		until, err := ParseUntilAtNow(opts.Until, now)
34		if err != nil {
35			return nil, err
36		}
37		normalizedSince, normalizedUntil := NormalizeWindow(since, until)
38		if !normalizedSince.Before(normalizedUntil) {
39			return nil, errors.New("--since must be before --until")
40		}
41	
42		repos := append([]string(nil), opts.RepoPaths...)
43		orgs := append([]string(nil), opts.Orgs...)
44		if len(orgs) == 0 && len(repos) == 0 {
45			repoRoot, err := paths.WorktreeRoot(ctx)
46			if err != nil {
47				return nil, fmt.Errorf("not in a git repository: %w", err)
48			}
49			repo, err := git.PlainOpenWithOptions(repoRoot, &git.PlainOpenOptions{DetectDotGit: true})
50			if err != nil {
51				return nil, fmt.Errorf("open repository: %w", err)
52			}
53			repoFullName, err := resolveRepoFullName(repo)
54			if err != nil {
55				return nil, err
56			}
57			repos = []string{repoFullName}
58		}
59	
60		cloud := NewCloudClient(CloudConfig{BaseURL: api.BaseURL(), Token: token})
61		reqBody := CreateDispatchRequest{
62			Repos:       repos,
63			Orgs:        orgs,
64			Since:       normalizedSince.Format(time.RFC3339),
65			Until:       normalizedUntil.Format(time.RFC3339),
66			Branches:    append([]string(nil), opts.Branches...),
67			AllBranches: opts.AllBranches,
68			Generate:    true,
69			Voice:       resolvedDispatchVoicePreference(opts.Voice),
70		}
71		response, err := cloud.CreateDispatch(ctx, reqBody)
72		if err != nil {
73			return nil, err
74		}
75	
76		dispatch := apiToDispatch(response)
77		if strings.TrimSpace(dispatch.GeneratedText) == "" {
78			return nil, errDispatchMissingMarkdown
79		}
80		return dispatch, nil
81	}
